# --- s028 Book I d.4 q.2 = Ord. I d.4 p.2 q.un. (Vat. nn.7-14)
n("n493","s028-01","Secunda questio quarte distinctionis","la","source","= *Ord.* I d. 4 p. 2 q. un. (ed. Vat. IV, nn. 7–14), *de veritate huius 'Deus est Pater et Filius et Spiritus Sanctus'*. Gorris's D4 has only these two questions, as the Vatican edition does.","certain")
n("n494","s028-01","Aug. 8. de trini.","la","source","Ord. n. 8 cites Augustine for *Pater et Filius et Spiritus Sanctus sunt unus Deus* (cf. *De Trin.* VIII prooem. 1, *unus Deus*). The book number is not verified in the Vatican apparatus.","to-verify")
n("n495","s028-02","nam deus naturam significat diuinam vt natam predicari de suppositis","la","source","*Ord.* I d. 4 n. 9: *terminus quod primo significat, hoc primo ponit in oratione* (‘Deus’ signifies the deity as *haec*, with co-reference to a supposit).","certain")
n("n496","s028-02","est idem ydemptice","la","textual","A *ē idē ydēptice*, B *est idē identitate*; later A *deitas ydemptica*, B *deitas identitate*. The contrast between formal predication (*Filius est Deus*) and identical predication (*Filius est deitas*) is Scotus's own (*Ord.* I d. 4 n. 10; cf. d. 8 on *praedicatio identica*).","certain")
n("n497","s028-03","quatenus deus extat pro hoc deo in quantum est ens per se deitate","la","source","*Ord.* I d. 4 nn. 11–13: *Deus* stands for *hic Deus*, for the deity as *per se ens*, not for a supposit determined by a personal property. *extat* is Gorris's *stat*.","certain")
n("n498","s028-03","Color disgregat","la","source","*Ord.* I d. 4 n. 12: *color 'hic', singularis exsistens, non determinat sibi rationem suppositi…*. The example *color disgregat [visum]* comes from Arist. *Top.* III 5 (119a30) and *Metaph.* X 7 (1057b8).","certain")
n("n499","s028-03","committitur fallacia","la","source","*Ord.* I d. 4 n. 14: the proposed contradictory is not one if the distribution is over the persons. Gorris does not name the fallacy.","certain")

# --- B collation (full): B41L–B41R
n("n1112","s028-01","videtur esse vera","la","textual","B: *est vera*.","certain")
n("n1113","s028-02","per concernentiam ad suppositum","la","textual","B: *vt natam predicari de supposito*, repeating the formula of the previous sentence.","certain")
n("n1114","s028-02","quasi inuersa","la","textual","B: *quasi inconuersa*.","certain")
upd("n497", append=" B: *quatenus deus stat pro deo*.")
